const payload = ($input.first().json.body) || $input.first().json;
const event = payload.event;

if (event !== 'message_created') {
  console.log('[cw-ai] skip event=' + event);
  return [{ json: { skipped: true, skip_reason: 'not_message_created', event } }];
}

const msgType = payload.message_type;
if (msgType === 1 || msgType === 'outgoing') {
  console.log('[cw-ai] skip outgoing id=' + payload.id);
  return [{ json: { skipped: true, skip_reason: 'outgoing', message_id: payload.id } }];
}

if (payload.private === true) {
  console.log('[cw-ai] skip private_note id=' + payload.id);
  return [{ json: { skipped: true, skip_reason: 'private_note', message_id: payload.id } }];
}

const senderType = (payload.sender && payload.sender.type) ? payload.sender.type : '';
if (senderType === 'agent_bot' || senderType === 'bot') {
  console.log('[cw-ai] skip bot_message id=' + payload.id);
  return [{ json: { skipped: true, skip_reason: 'bot_message', message_id: payload.id } }];
}

const attachments = Array.isArray(payload.attachments) ? payload.attachments : [];
const hasAttachments = attachments.length > 0;
const contentType = payload.content_type || 'text';
const rawContent = (payload.content || '').trim();
const lowerContent = rawContent.toLowerCase();
const isVoicePlaceholder = lowerContent.startsWith('voice message:') || lowerContent.startsWith('audio message:');
const isImagePlaceholder = lowerContent.startsWith('image message:') || lowerContent.startsWith('photo message:') || lowerContent.startsWith('picture message:') || lowerContent.startsWith('photo:');
const isPlaceholder = !rawContent || lowerContent === '(no text content)' || isVoicePlaceholder || isImagePlaceholder;

if (contentType && contentType !== 'text' && contentType !== 'input_select' && !hasAttachments) {
  console.log('[cw-ai] skip non_text=' + contentType + ' id=' + payload.id);
  return [{ json: { skipped: true, skip_reason: 'non_text:' + contentType, message_id: payload.id } }];
}

if (!rawContent && !hasAttachments) {
  console.log('[cw-ai] skip empty_content id=' + payload.id);
  return [{ json: { skipped: true, skip_reason: 'empty_content', message_id: payload.id } }];
}

const content = rawContent || (hasAttachments ? '(no text content)' : '');

const convId  = payload.conversation && payload.conversation.id;
const accountId = (payload.account && payload.account.id) || 2;
if (!convId) {
  return [{ json: { skipped: true, skip_reason: 'no_conversation_id', message_id: payload.id } }];
}

const messageId = parseInt(String(payload.id), 10);
const convIdInt = parseInt(String(convId), 10);

// Build the atomic PG lock query (injecting safe integer values)
const pgLockQuery = [
  "WITH ins AS (",
  "  INSERT INTO cw_ai_idempotency",
  "    (chatwoot_message_id, conversation_id, status, created_at, updated_at)",
  "  VALUES (" + messageId + "::BIGINT, " + convIdInt + "::BIGINT, 'processing', NOW(), NOW())",
  "  ON CONFLICT (chatwoot_message_id) DO UPDATE",
  "    SET status = 'processing', updated_at = NOW()",
  "    WHERE cw_ai_idempotency.status = 'processing'",
  "      AND cw_ai_idempotency.updated_at < NOW() - INTERVAL '10 minutes'",
  "  RETURNING true AS action_taken",
  ")",
  "SELECT",
  "  t.chatwoot_message_id,",
  "  t.status,",
  "  EXTRACT(EPOCH FROM (NOW() - t.updated_at))/60.0 AS minutes_ago,",
  "  COALESCE(t.error_message, '') AS error_message,",
  "  COALESCE((SELECT action_taken FROM ins LIMIT 1), false) AS action_taken",
  "FROM cw_ai_idempotency t",
  "WHERE t.chatwoot_message_id = " + messageId + "::BIGINT"
].join('\n');

return [{
  json: {
    skipped: false,
    message_id: messageId,
    conversation_id: convIdInt,
    account_id: parseInt(String(accountId), 10) || 2,
    content: content,
    raw_content: rawContent,
    attachments: attachments,
    has_attachments: hasAttachments,
    is_attachment_only: isPlaceholder && hasAttachments,
    sender_name: (payload.sender && payload.sender.name) || 'Customer',
    sender_type: senderType,
    content_type: contentType,
    pg_lock_query: pgLockQuery
  }
}];

const item = $input.first().json;
console.log('[cw-ai] SKIP reason=' + item.skip_reason + ' msg=' + (item.message_id || 'n/a') + ' event=' + (item.event || ''));
return [{ json: { result: 'skipped', ...item } }];

const rows = $input.all();
const filterData = $('Filter Events').first().json;
const messageId = filterData.message_id;

// n8n Postgres node returns {success: true} (no row data) when INSERT succeeded
// (no conflict). When there IS a conflict, it returns the actual SELECT row.
// This is the reliable way to detect if WE just inserted vs. found existing record.
const firstItem = rows[0] ? rows[0].json : {};

const insertSucceeded = (
  firstItem.success === true && !firstItem.chatwoot_message_id
) || (
  // Also handle case where row returned but action_taken explicitly true
  firstItem.action_taken === true || firstItem.action_taken === 't' || firstItem.action_taken === 'true'
);

if (insertSucceeded) {
  console.log('[cw-ai] idem LOCKED (new insert or stale-reset) message_id=' + messageId);
  return [{ json: { ...filterData, should_process: true, lock_reason: 'acquired' } }];
}

// We have the existing row data — conflict detected
const row = firstItem;
const st = row.status;
const mins = parseFloat(row.minutes_ago) || 0;

if (!st) {
  // No status data at all — proceed cautiously (shouldn't happen)
  console.log('[cw-ai] idem no_status message_id=' + messageId + ' — proceeding cautiously');
  return [{ json: { ...filterData, should_process: true, lock_reason: 'no_status_fallback' } }];
}

if (st === 'done') {
  console.log('[cw-ai] idem SKIP already_done message_id=' + messageId);
  return [{ json: { ...filterData, should_process: false, skip_reason: 'already_done' } }];
}

if (st === 'processing' && mins < 10) {
  console.log('[cw-ai] idem SKIP in_progress message_id=' + messageId + ' age=' + mins.toFixed(1) + 'min');
  return [{ json: { ...filterData, should_process: false, skip_reason: 'in_progress_' + Math.round(mins) + 'min' } }];
}

if (st === 'error') {
  const errSnip = String(row.error_message || '').substring(0, 80);
  console.log('[cw-ai] idem SKIP previous_error message_id=' + messageId + ' err=' + errSnip);
  return [{ json: { ...filterData, should_process: false, skip_reason: 'previous_error:' + errSnip } }];
}

// Stale processing lock (>= 10 min) that the DO UPDATE WHERE condition should have reset;
// if we somehow still land here, allow processing
console.log('[cw-ai] idem stale_fallback message_id=' + messageId + ' state=' + st + ' age=' + mins.toFixed(1) + 'min — proceeding');
return [{ json: { ...filterData, should_process: true, lock_reason: 'stale_fallback' } }];

const item = $input.first().json;
console.log('[cw-ai] IDEM_SKIP reason=' + item.skip_reason + ' message_id=' + item.message_id);
return [{ json: { result: 'idem_skipped', message_id: item.message_id, skip_reason: item.skip_reason } }];

const conv = $input.first().json;
const ctx = $('Evaluate Lock').first().json;

const sender = (conv.meta && conv.meta.sender) || {};
const senderCustom = (sender.custom_attributes && typeof sender.custom_attributes === 'object')
  ? sender.custom_attributes
  : {};
let groupJid = String(senderCustom.group_jid || senderCustom.whatsapp_jid || sender.identifier || '').trim();
const managedKey = String(senderCustom.managed_group_key || '').trim();
if (!groupJid && managedKey.startsWith('wa-')) {
  groupJid = managedKey.replace(/^wa-/, '') + '@g.us';
}

return [{
  json: {
    ...ctx,
    group_jid: groupJid || null,
    conversation: conv,
  }
}];

const lookup = $input.first().json;
const wrap = $('Extract Group Jid').first().json;
const conv = wrap.conversation || {};
const ctx = wrap;

const customAttrs = conv.custom_attributes || {};
let stickyWpId = customAttrs.openproject_wp_id;
if (stickyWpId !== undefined && stickyWpId !== null && stickyWpId !== '') {
  const parsed = parseInt(String(stickyWpId), 10);
  stickyWpId = isNaN(parsed) ? null : parsed;
} else {
  stickyWpId = null;
}
let lastWpId = customAttrs.last_openproject_wp_id;
if (lastWpId !== undefined && lastWpId !== null && lastWpId !== '') {
  const parsedLast = parseInt(String(lastWpId), 10);
  lastWpId = isNaN(parsedLast) ? null : parsedLast;
} else {
  lastWpId = null;
}

// Active request window (attachment + text + clarification → one WP)
let activeRequestWpId = customAttrs.cw_ai_active_request_wp_id;
if (activeRequestWpId !== undefined && activeRequestWpId !== null && activeRequestWpId !== '') {
  const parsedActive = parseInt(String(activeRequestWpId), 10);
  activeRequestWpId = isNaN(parsedActive) ? null : parsedActive;
} else {
  activeRequestWpId = null;
}
const activeUntilRaw = customAttrs.cw_ai_active_request_until;
const activeUntil = activeUntilRaw ? Date.parse(String(activeUntilRaw)) : NaN;
const activeRequestValid = Boolean(
  activeRequestWpId && !isNaN(activeUntil) && activeUntil >= Date.now()
);
const requestWindowMinutes = parseInt(String($env.CHATWOOT_AI_REQUEST_WINDOW_MINUTES || '15'), 10) || 15;

const senderName = (conv.meta && conv.meta.sender && conv.meta.sender.name)
  ? conv.meta.sender.name
  : ctx.sender_name;

const labels = Array.isArray(conv.labels) ? conv.labels : [];
const groupJid = wrap.group_jid || null;
const groupEntry = (lookup && lookup.ok) ? (lookup.entry || lookup) : null;
const opProjectIdRaw = groupEntry && groupEntry.project_id != null ? parseInt(String(groupEntry.project_id), 10) : null;
const opProjectId = (opProjectIdRaw && !isNaN(opProjectIdRaw)) ? opProjectIdRaw : null;
const opProjectIdentifier = groupEntry ? String(groupEntry.project_identifier || '') : '';
const managedChatwootLabel = groupEntry ? String(groupEntry.chatwoot_label || '') : '';
const managedGroup = Boolean(groupEntry && groupEntry.managed);
const company = groupEntry ? String(groupEntry.company || '').trim().toLowerCase() : '';

// Explicit OP# / WP# in message body (e.g. UAT on OP#86)
const msgText = String(ctx.raw_content || ctx.content || '');
const opRefMatch = msgText.match(/\bOP\s*#\s*(\d+)\b/i) || msgText.match(/\bWP\s*#\s*(\d+)\b/i);
const referencedOpWpId = opRefMatch ? parseInt(opRefMatch[1], 10) : null;

// Dev Needed (and similar multi-client inboxes) must NOT pin all messages to one sticky WP.
// Sticky openproject_wp_id previously forced every message onto WP#117 and blocked auto-create.
const isMultiClientInbox = managedChatwootLabel === 'dev-needed'
  || labels.includes('dev-needed')
  || String($env.CHATWOOT_MULTI_CLIENT_LABELS || 'dev-needed').split(',').map(s => s.trim()).filter(Boolean)
      .some(l => labels.includes(l) || managedChatwootLabel === l);

// Parent bucket routing for new WPs (Dev Needed children under company parents)
const PARENT_BY_WP = {
  86: 87, 87: 87, 206: 87,
  88: 88, 135: 88, 168: 88, 205: 88,
  89: 89,
  90: 90,
  91: 91,
  92: 92,
  93: 93,
  94: 94,
  95: 96, 96: 96
};
const PARENT_BY_KEYWORD = [
  { re: /كفاءات|kafaat|openeducat|student\s*registration|blood\s*group|trainee/i, parent: 87 },
  { re: /خليج|gpc\.odoo|legacy_mixed|trgulf|trgcc|projects\s*analysis/i, parent: 88 },
  { re: /شموخ|asasat|alshmoukh/i, parent: 96 },
  { re: /زليق|zaleq|alzoliq/i, parent: 93 },
  { re: /\bnadco\b|نادكو/i, parent: 91 },
  { re: /اجازة|إجازة|leave\s*request|شؤون الموظفين|شؤون الموظفين|نموذج طلب/i, parent: 91 },
  { re: /edafa|إدافة|\[edafa\]/i, parent: parseInt(String($env.OPENPROJECT_EDAFA_PARENT_ID || ''), 10) || null },
  { re: /\basta\b/i, parent: 89 },
  { re: /ابداع|ebdaa/i, parent: 90 }
];
let routedParentId = null;
if (referencedOpWpId && PARENT_BY_WP[referencedOpWpId]) {
  routedParentId = PARENT_BY_WP[referencedOpWpId];
} else {
  for (const row of PARENT_BY_KEYWORD) {
    if (row.parent && row.re.test(msgText)) { routedParentId = row.parent; break; }
  }
}

const hasAttachments = Boolean(ctx.has_attachments);
const isShortFollowUp = Boolean(ctx.is_attachment_only) || msgText.trim().length < 30;
const attNames = (Array.isArray(ctx.attachments) ? ctx.attachments : [])
  .map(a => String(a.file_name || a.filename || '').trim()).join(' ');
const attLabel = (msgText + ' ' + attNames).trim();
const isHrLeave = /اجازة|إجازة|leave|شؤون الموظفين|شؤون الموظفين|نموذج طلب/i.test(attLabel);
const isAssetFollowUp = /asset|أصول|اكسل|xlsx|account\.asset|revenue/i.test(attLabel);

// Sticky is a CANDIDATE only. Blind reuse of closed/unrelated sticky WPs is forbidden.
// Validation (status/project/follow-up) runs in "Decide Sticky WP" after AI analysis.
let wpId = null;
let stickyCandidateWpId = null;
if (isMultiClientInbox) {
  if (hasAttachments && lastWpId && isShortFollowUp && !referencedOpWpId && !isHrLeave && isAssetFollowUp) {
    wpId = lastWpId;
  } else {
    wpId = null;
  }
} else if (referencedOpWpId) {
  wpId = referencedOpWpId;
} else if (activeRequestValid) {
  wpId = activeRequestWpId;
} else {
  stickyCandidateWpId = stickyWpId;
  wpId = null;
}

// Re-run parent routing with attachment filenames (WhatsApp often puts filename in body)
if (!routedParentId) {
  for (const row of PARENT_BY_KEYWORD) {
    if (row.parent && row.re.test(attLabel)) { routedParentId = row.parent; break; }
  }
}

console.log('[cw-ai] ctx msg=' + ctx.message_id + ' conv=' + ctx.conversation_id
  + ' wp=' + wpId + ' sticky=' + stickyWpId + ' sticky_candidate=' + stickyCandidateWpId
  + ' active_req=' + (activeRequestValid ? activeRequestWpId : null)
  + ' last_wp=' + lastWpId + ' ref_op=' + referencedOpWpId
  + ' parent_route=' + routedParentId + ' multi_client=' + isMultiClientInbox
  + ' has_att=' + hasAttachments + ' asset_follow=' + isAssetFollowUp + ' hr_leave=' + isHrLeave
  + ' labels=' + labels.join(',') + ' group=' + (groupJid || 'none')
  + ' op_project=' + (opProjectId || 'default'));
return [{
  json: {
    message_id: ctx.message_id,
    conversation_id: ctx.conversation_id,
    account_id: ctx.account_id,
    content: ctx.content,
    raw_content: ctx.raw_content || ctx.content,
    attachments: ctx.attachments || [],
    has_attachments: hasAttachments,
    is_attachment_only: Boolean(ctx.is_attachment_only),
    sender_name: senderName,
    openproject_wp_id: wpId,
    referenced_op_wp_id: referencedOpWpId,
    routed_op_parent_id: routedParentId,
    sticky_openproject_wp_id: stickyWpId,
    sticky_candidate_wp_id: stickyCandidateWpId,
    last_openproject_wp_id: lastWpId,
    active_request_wp_id: activeRequestValid ? activeRequestWpId : null,
    request_window_minutes: requestWindowMinutes,
    multi_client_inbox: isMultiClientInbox,
    conversation_labels: labels,
    content_length: (ctx.content || '').trim().length,
    conversation_status: conv.status,
    conversation_inbox_id: conv.inbox_id,
    group_jid: groupJid || null,
    op_project_id: opProjectId,
    op_project_identifier: opProjectIdentifier || null,
    managed_chatwoot_label: managedChatwootLabel || null,
    managed_group: managedGroup,
    company: company || null
  }
}];

const ctx = $('Build Context').first().json;
const resp = $input.first().json;
const list = Array.isArray(resp.payload) ? resp.payload : [];

let msg = null;
for (const item of list) {
  if (parseInt(String(item.id), 10) === parseInt(String(ctx.message_id), 10)) {
    msg = item;
    break;
  }
}

let content = ctx.content;
let rawContent = ctx.raw_content || ctx.content;
let attachments = Array.isArray(ctx.attachments) ? ctx.attachments : [];
let contentLength = ctx.content_length || (content || '').length;

if (msg) {
  const apiContent = String(msg.content || '').trim();
  if (apiContent) {
    rawContent = apiContent;
    content = apiContent;
    contentLength = apiContent.length;
  }
  if (Array.isArray(msg.attachments) && msg.attachments.length) {
    attachments = msg.attachments;
  }
}

console.log('[cw-ai] merged msg=' + ctx.message_id + ' content_len=' + contentLength + ' atts=' + attachments.length + ' fetched=' + Boolean(msg));

return [{
  json: {
    ...ctx,
    content,
    raw_content: rawContent,
    attachments,
    has_attachments: attachments.length > 0,
    content_length: contentLength,
    message_fetch_ok: Boolean(msg)
  }
}];

const ctx = $('Merge Message Into Context').first().json;
const raw = $input.first().json;
const pre = (raw && raw.ok !== undefined) ? raw : {};

const attachmentContext = pre.attachment_context || {
  has_attachment: Boolean(ctx.has_attachments),
  attachment_type: ctx.has_attachments ? 'unknown' : 'none',
  preprocess_status: pre.error ? 'failed' : 'skipped',
  extracted_text: '',
  description: '',
  error: pre.error || null
};

let normalizedContent = (
  pre.normalized_content ||
  attachmentContext.extracted_text ||
  attachmentContext.description ||
  ctx.content ||
  ''
).trim();

if (!normalizedContent && ctx.is_attachment_only) {
  normalizedContent = 'Attachment received with no extractable text.';
}

const analyzerInput = normalizedContent || ctx.content || 'Attachment received with no extractable text.';
const skipAi = Boolean(pre.skip_ai);

console.log(
  '[cw-ai] preprocess msg=' + ctx.message_id +
  ' status=' + (attachmentContext.preprocess_status || 'none') +
  ' type=' + (attachmentContext.attachment_type || 'none') +
  ' chars=' + analyzerInput.length
);

return [{
  json: {
    ...ctx,
    normalized_content: analyzerInput,
    attachment_context: attachmentContext,
    attachments: pre.attachments || ctx.attachments || [],
    needs_preprocessing: Boolean(pre.needs_preprocessing || ctx.is_attachment_only),
    skip_ai: skipAi,
    preprocess_ok: pre.ok !== false && !pre.error,
    default_category: pre.default_category || 'support',
    content_length: analyzerInput.length
  }
}];

const ctx = $input.first().json;

function capText(text, maxChars) {
  const s = String(text || '').trim();
  if (s.length <= maxChars) return s;
  return s.substring(0, maxChars) + '... [truncated]';
}

const attCtx = ctx.attachment_context || {};
const attType = attCtx.attachment_type || 'none';
let contentCap = 3000;
if (attType === 'image') contentCap = 2000;

const systemPrompt = "You are an Odoo developer triage assistant. The team builds and supports Odoo ERP for customers. Treat incoming issues as Odoo bugs, RPC errors, custom module defects, or Odoo configuration work unless clearly unrelated.\nWhen the message contains Odoo traceback or RPC_ERROR, extract model, custom module path, method name, exception type, and a concrete developer fix in action_required.\nRespond with JSON only. No markdown, no code fences, no extra text.\n\nConfidence rules:\n* confidence must be a number from 0.0 to 1.0.\n* Use 0.85-0.95 for clear actionable bug/task/feature requests.\n* Use 0.75-0.84 for actionable but incomplete requests.\n* Use 0.50-0.74 for ambiguous requests needing review.\n* Use below 0.50 for non-actionable chatter or unclear messages.\n* Do not return 0.0 unless the message is completely unrelated or impossible to classify.\n* If category is bug, support, or configuration and the summary is clear, confidence should normally be >= 0.75.\n\nSchema:\n{\"category\":\"support|sales|configuration|bug|accounting|other\",\"priority\":\"low|medium|high|urgent\",\"summary\":\"1-2 sentences for Odoo developers\",\"action_required\":\"concrete next step: file/method, code fix, deploy, retest\",\"project_hint\":\"Odoo WP subject max 80 chars (model + issue)\",\"language\":\"ar|en|mixed\",\"confidence\":0.88}";

const analyzerText = capText(ctx.normalized_content || ctx.content || '', contentCap);
const attachmentHint = attCtx.has_attachment
  ? '\n[attachment_type=' + (attCtx.attachment_type || 'unknown') +
    ', preprocess_status=' + (attCtx.preprocess_status || 'unknown') + ']'
  : '';

const userContent = 'Customer: ' + (ctx.sender_name || 'Customer') +
  '\n\nMessage:\n' + analyzerText + attachmentHint;

const openaiModel = $env.CHATWOOT_AI_OPENAI_MODEL || 'gpt-4o-mini';
const webuiModel = $env.OPENWEBUI_MODEL || 'qwen2.5:3b-instruct-q4_K_M';
const geminiModel = $env.CHATWOOT_AI_GEMINI_MODEL || 'gemini-2.0-flash';

const openaiBody = {
  model: openaiModel,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userContent }
  ],
  max_tokens: 250,
  temperature: 0.2,
  response_format: { type: 'json_object' }
};

const openwebuiBody = {
  model: webuiModel,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userContent }
  ],
  stream: false,
  max_tokens: 250,
  temperature: 0.2
};

const geminiBody = {
  contents: [{ parts: [{ text: systemPrompt + '\n\n' + userContent }] }],
  generationConfig: {
    maxOutputTokens: 250,
    temperature: 0.2,
    responseMimeType: 'application/json'
  },
  _model: geminiModel
};

const difyApiKey = String($env.DIFY_API_KEY_CHATWOOT_TRIAGE || $env.DIFY_API_KEY || '').trim();
let difyBase = String($env.DIFY_BASE_URL || '').trim().replace(/\/$/, '');
if (difyBase && !difyBase.endsWith('/v1')) difyBase += '/v1';
const difyInputs = {
  sender_name: ctx.sender_name || 'Customer',
  message_text: analyzerText,
  attachment_type: attCtx.attachment_type || 'none',
  preprocess_status: attCtx.preprocess_status || 'none',
  conversation_id: String(ctx.conversation_id || ''),
  message_id: String(ctx.message_id || '')
};
const difyBody = {
  inputs: difyInputs,
  response_mode: 'blocking',
  user: 'n8n-cw-' + (ctx.message_id || 'unknown')
};

return [{
  json: {
    ...ctx,
    analyzer_input: analyzerText,
    user_content: userContent,
    request_body: openaiBody,
    openai_request_body: openaiBody,
    openwebui_request_body: openwebuiBody,
    gemini_request_body: geminiBody,
    dify_request_body: difyBody,
    dify_base_url: difyBase,
    dify_api_key: difyApiKey,
    openai_model: openaiModel,
    webui_model: webuiModel,
    gemini_model: geminiModel,
    dify_model: 'dify-chatwoot-triage'
  }
}];

const ctx = $input.first().json;
const testMode = String($env.CHATWOOT_AI_TEST_MODE || '').toLowerCase() === 'true';
const validation = String($env.CHATWOOT_AI_PROVIDER_VALIDATION || '').toLowerCase() === 'true';
const configured = String($env.CHATWOOT_AI_FINAL_PROVIDER || 'openai').toLowerCase();
const webuiEnabled = String($env.CHATWOOT_AI_OPENWEBUI_ENABLED || 'false').toLowerCase() === 'true';

let finalProvider = configured;
if (testMode && !validation) {
  finalProvider = 'mock';
} else if (finalProvider === 'openwebui' && !webuiEnabled) {
  finalProvider = 'openai';
}
if (!['mock', 'openai', 'gemini', 'openwebui', 'dify'].includes(finalProvider)) {
  finalProvider = 'openai';
}
if (finalProvider === 'dify' && !String($env.DIFY_API_KEY || $env.DIFY_API_KEY_CHATWOOT_TRIAGE || '').trim()) {
  finalProvider = 'openai';
}

console.log('[cw-ai] final_provider=' + finalProvider + ' test=' + testMode + ' validation=' + validation);

return [{ json: { ...ctx, final_provider: finalProvider } }];

