// Mirror of infra/n8n/lib/sticky_wp.py — keep behaviors in sync.
// Always read analysis from Build Analysis Note (Fetch Sticky WP may be $input).
const anal = $('Build Analysis Note').first().json;
const ctx = $('Build Context').first().json;
const fetchItem = (() => {
  try { return $('Fetch Sticky WP').first().json; } catch (e) { return null; }
})();
const incoming = $input.first().json;
// When fetch path runs, incoming is WP payload; when not, incoming is analysis.
const fetchFromInput = incoming && (incoming.id || incoming._type === 'WorkPackage' || incoming.error || incoming.statusCode);
const effectiveFetch = fetchFromInput ? incoming : fetchItem;

const stickyCandidate = anal.sticky_candidate_wp_id || ctx.sticky_candidate_wp_id || null;
let wpId = anal.openproject_wp_id || null;
let rejectReason = null;
let clearSticky = false;
let stickyFetchStatus = null;

const NEW_TASK_RE = /(?:\bnew\s+(?:task|ticket|wp|work[\s-]*package)\b|\bcreate\s+(?:a\s+)?(?:new\s+)?(?:task|ticket|wp)\b|تاسك\s*جديد|مهمة\s*جديدة|طلب\s*جديد|\bnew\s+request\b)/i;
const REOPEN_RE = /(?:\bre-?open\b|\breopen\b|\bcontinue\s+(?:on|with)\s+(?:OP|WP)\s*#?\s*\d+|افتح\s*تاني|إعادة\s*فتح)/i;
const FOLLOW_RE = /(?:\bfyi\b|\bas\s+above\b|\bsame\s+(?:issue|task|ticket)\b|\bfollow[\s-]*up\b|\bupdate\b|\bclarif|نفس\s*(?:الموضوع|التاسك|الطلب)|متابعة|توضيح)/i;

function isTerminal(status) {
  const s = String(status || '').trim().toLowerCase();
  if (!s) return false;
  return ['closed', 'rejected', 'cancelled', 'canceled'].some(t => s === t || s.includes(t));
}

if (!wpId && stickyCandidate) {
  const msgText = String(anal.raw_content || anal.content || '');
  const aiMeta = anal.ai_meta || {};
  const actionable = aiMeta.actionable === true;
  const contentLen = anal.content_length || msgText.trim().length;
  const isAttOnly = Boolean(anal.is_attachment_only);
  const expectedProject = ctx.op_project_id ? parseInt(String(ctx.op_project_id), 10) : null;

  let wpExists = false;
  let wpStatus = null;
  let wpProjectId = null;
  const f = effectiveFetch;
  if (f && !f.error && (f.id || (f._type === 'WorkPackage'))) {
    wpExists = true;
    stickyFetchStatus = 'ok';
    wpStatus = (f._links && f._links.status && f._links.status.title)
      ? f._links.status.title
      : (f.status || null);
    const projHref = f._links && f._links.project && f._links.project.href;
    if (projHref) {
      const m = String(projHref).match(/\/projects\/(\d+)/);
      if (m) wpProjectId = parseInt(m[1], 10);
    }
  } else if (f && (f.error || f.statusCode === 404 || f.httpCode === 404 || f.status === 404)) {
    stickyFetchStatus = 'missing';
    wpExists = false;
  } else if (!f) {
    // Candidate path should always fetch; refuse blind reuse.
    stickyFetchStatus = 'no_fetch';
    wpExists = false;
  } else {
    stickyFetchStatus = 'error';
    wpExists = false;
  }

  if (anal.referenced_op_wp_id) {
    wpId = parseInt(String(anal.referenced_op_wp_id), 10);
  } else if (!wpExists) {
    rejectReason = 'sticky_wp_rejected_missing';
    // Only archive sticky when OP confirms missing (404), not on transport errors.
    clearSticky = (stickyFetchStatus === 'missing');
  } else if (expectedProject && wpProjectId && wpProjectId !== expectedProject) {
    rejectReason = 'sticky_wp_rejected_wrong_project';
    clearSticky = true;
  } else if (isTerminal(wpStatus) && !REOPEN_RE.test(msgText)) {
    rejectReason = 'sticky_wp_rejected_closed';
    clearSticky = true;
  } else if (NEW_TASK_RE.test(msgText)) {
    rejectReason = 'sticky_wp_rejected_new_task_intent';
    clearSticky = true;
  } else {
    const short = isAttOnly || msgText.trim().length < 30;
    const followHint = FOLLOW_RE.test(msgText);
    if (!short && !followHint && !isAttOnly && contentLen >= 40 && actionable) {
      rejectReason = 'sticky_wp_rejected_unrelated';
      clearSticky = true;
    } else {
      wpId = parseInt(String(stickyCandidate), 10);
    }
  }
}

let noteContent = anal.note_content || '';
if (wpId && noteContent && !noteContent.includes('cw-ai-wp-updated:')) {
  noteContent = noteContent + '\n\n<!-- cw-ai-wp-updated:' + anal.message_id + ' wp=' + wpId + ' -->';
}
if (rejectReason) {
  noteContent = noteContent + '\n\n<!-- cw-ai-sticky-rejected:' + anal.message_id + ' reason=' + rejectReason + ' sticky=' + stickyCandidate + ' -->';
  console.log('[cw-ai] sticky rejected reason=' + rejectReason + ' sticky=' + stickyCandidate);
} else if (wpId) {
  console.log('[cw-ai] sticky reuse wp=' + wpId + ' fetch=' + stickyFetchStatus);
}

return [{
  json: {
    ...anal,
    openproject_wp_id: wpId,
    note_content: noteContent,
    sticky_reject_reason: rejectReason,
    clear_sticky: clearSticky,
    sticky_fetch_status: stickyFetchStatus,
    sticky_candidate_wp_id: stickyCandidate
  }
}];

