const approvedLabels = String($env.CHATWOOT_AI_CREATE_LABELS || 'ai-create-wp')
  .split(',').map(s => s.trim()).filter(Boolean);
const minConf = parseFloat($env.CHATWOOT_AI_MIN_CONFIDENCE || '0.75');
const minLen = parseInt($env.CHATWOOT_AI_MIN_MESSAGE_LENGTH || '20', 10);
const defaultProjectId = parseInt(String($env.OPENPROJECT_DEFAULT_PROJECT_ID || ''), 10);
const typeId = parseInt(String($env.OPENPROJECT_DEFAULT_TYPE_ID || ''), 10);

const labels = anal.conversation_labels || ctx.conversation_labels || [];
const hasExplicitLabel = approvedLabels.some(l => labels.includes(l));
const hasManagedLabel = Boolean(
  ctx.managed_group &&
  ctx.managed_chatwoot_label &&
  labels.includes(ctx.managed_chatwoot_label)
);
const hasLabel = hasExplicitLabel || hasManagedLabel;

const resolvedProjectId = (ctx.op_project_id && !isNaN(parseInt(String(ctx.op_project_id), 10)))
  ? parseInt(String(ctx.op_project_id), 10)
  : null;
const projectId = resolvedProjectId || defaultProjectId;

const aiMeta = anal.ai_meta || {};
let actionable = aiMeta.actionable === true;
const confidence = parseFloat(aiMeta.confidence) || 0;
const contentLen = anal.content_length || (anal.content || '').trim().length;
const hasAttachments = Boolean(anal.has_attachments || (Array.isArray(anal.attachments) && anal.attachments.length));
const attLabel = String(anal.raw_content || anal.content || '') + ' ' + (Array.isArray(anal.attachments) ? anal.attachments.map(a => a.file_name || a.filename || '').join(' ') : '');
const isHrLeave = /اجازة|إجازة|leave|شؤون الموظفين|شؤون الموظفين|نموذج طلب/i.test(attLabel);
const isAssetFile = /asset|أصول|اكسل|xlsx|account\.asset|revenue|\.xlsx|\.docx/i.test(attLabel);
const minConfWithAtt = parseFloat($env.CHATWOOT_AI_MIN_CONFIDENCE_WITH_ATTACHMENT || '0.40');
const effectiveMinConf = hasAttachments ? Math.min(minConf, minConfWithAtt) : minConf;

// Attachment-only / file messages should still create or route work packages.
if (hasAttachments && (isHrLeave || isAssetFile || anal.is_attachment_only)) {
  actionable = true;
  if (!aiMeta.suggested_wp_subject && attLabel.trim()) {
    aiMeta.suggested_wp_subject = attLabel.trim().substring(0, 80);
  }
  if (!aiMeta.request_type || aiMeta.request_type === 'other') {
    aiMeta.request_type = isHrLeave ? 'configuration' : 'configuration';
  }
}

const failures = [];
// DEVHUB_INTAKE_MODE_SKIP: Dev Hub owns intake for pilot group — skip legacy OpenProject auto-create.
const groupJid = String(ctx.group_jid || anal.group_jid || ctx.remote_jid || '').trim();
const DEVHUB_INTAKE_JIDS = new Set([
  '120363411424964076@g.us', // testopenclow
]);
const intakeModeHint = String(ctx.devhub_intake_mode || anal.devhub_intake_mode || $env.DEVHUB_INTAKE_MODE_OVERRIDE || '').trim();
const skipLegacyOpForDevhub = DEVHUB_INTAKE_JIDS.has(groupJid) || intakeModeHint === 'devhub';
if (skipLegacyOpForDevhub) {
  failures.push('devhub_intake_mode');
}

if (!hasLabel) failures.push('missing_label:' + approvedLabels.join('|'));
if (!actionable) failures.push('not_actionable:request_type=' + (aiMeta.request_type || 'unknown'));
if (confidence < effectiveMinConf) failures.push('low_confidence:' + confidence.toFixed(2) + '<' + effectiveMinConf);
if (!hasAttachments && contentLen < minLen) failures.push('message_too_short:' + contentLen + '<' + minLen);
if (ctx.managed_group && ctx.group_jid && !resolvedProjectId) {
  failures.push('missing_group_project_mapping:' + ctx.group_jid);
}
if (!projectId || isNaN(projectId)) failures.push('missing_op_project_mapping');
if (!typeId || isNaN(typeId)) failures.push('missing_op_type_mapping');

const eligible = failures.length === 0;
console.log('[cw-ai] auto-create gates eligible=' + eligible + ' project=' + projectId + ' managed=' + hasManagedLabel + ' failures=' + failures.join(';'));

return [{
  json: {
    ...anal,
    auto_create_eligible: eligible,
    gate_failures: failures,
    gate_fail_reason: failures.join('; ') || null,
    approved_labels: approvedLabels,
    op_project_id: projectId,
    op_project_identifier: ctx.op_project_identifier || null,
    op_type_id: typeId,
    // Prefer parent routed from OP# / keywords (e.g. OP#86 → kafaat #87); else env default.
    op_parent_id: (anal.routed_op_parent_id || ctx.routed_op_parent_id
      || parseInt(String($env.OPENPROJECT_DEFAULT_PARENT_ID || ''), 10) || null),
    ai_meta: aiMeta,
    referenced_op_wp_id: anal.referenced_op_wp_id || ctx.referenced_op_wp_id || null,
    op_assignee_id: parseInt(String($env.OPENPROJECT_DEFAULT_ASSIGNEE_ID || ''), 10) || null,
    op_public_url: String($env.OPENPROJECT_PUBLIC_BASE_URL || '').replace(/\/$/, '')
  }
}];

const g = $input.first().json;
const reason = g.gate_fail_reason || 'unknown';
const marker = '<!-- cw-ai-gate-fail:' + g.message_id + ' -->';

let humanReason;
if (reason.includes('missing_label')) {
  humanReason = 'لم يتم إنشاء Work Package لأن المحادثة لا تحتوي على التصنيف المطلوب (`ai-create-wp`) أو تصنيف مجموعة WhatsApp المُدارة.

أضف التصنيف ثم أعد المحاولة أو عيّن `openproject_wp_id` يدوياً.';
} else if (reason.includes('low_confidence')) {
  humanReason = 'لم يتم إنشاء Work Package لأن ثقة التحليل منخفضة.

التفاصيل: ' + reason;
} else if (reason.includes('not_actionable')) {
  humanReason = 'لم يتم إنشاء Work Package لأن الرسالة ليست طلباً قابلاً للتنفيذ.

التفاصيل: ' + reason;
} else if (reason.includes('message_too_short')) {
  humanReason = 'لم يتم إنشاء Work Package لأن نص الرسالة قصير جداً.

التفاصيل: ' + reason;
} else if (reason.includes('missing_group_project_mapping')) {
  humanReason = 'لم يتم إنشاء Work Package لأن مجموعة WhatsApp غير مربوطة بمشروع OpenProject.

التفاصيل: ' + reason;
} else if (reason.includes('missing_op')) {
  humanReason = 'لم يتم إنشاء Work Package لأن إعدادات OpenProject غير مكتملة.

التفاصيل: ' + reason;
} else {
  humanReason = 'لم يتم إنشاء Work Package.

التفاصيل: ' + reason;
}

const noteContent = marker + '
ℹ️ **لم يُنشأ Work Package في OpenProject**

' + humanReason;
const pgMarkDoneQuery = 'UPDATE cw_ai_idempotency SET status = \'done\', updated_at = NOW() WHERE chatwoot_message_id = ' + g.message_id + '::BIGINT';

return [{
  json: {
    message_id: g.message_id,
    conversation_id: g.conversation_id,
    account_id: g.account_id,
    note_content: noteContent,
    pg_mark_done_query: pgMarkDoneQuery
  }
}];

const g = $input.first().json;
const projectId = g.op_project_id;
const parentId = g.op_parent_id;
const subject = String((g.ai_meta && g.ai_meta.suggested_wp_subject) || g.content || '').trim();

const filters = [{ project: { operator: '=', values: [String(projectId)] } }];
if (parentId) filters.push({ parent: { operator: '=', values: [String(parentId)] } });
filters.push({ status: { operator: 'o', values: [] } });

const searchUrl = 'http://openproject/api/v3/work_packages?filters=' + encodeURIComponent(JSON.stringify(filters)) + '&pageSize=30';

return [{ json: { ...g, op_search_url: searchUrl, op_search_subject: subject } }];

const g = $('Build OP Duplicate Search').first().json;
let resp = $input.first().json;

// Fail-safe: if OP search errors, block create and force manual review.
const searchFailed = !!(
  resp.error ||
  resp.name === 'AxiosError' ||
  resp.code === 'ECONNREFUSED' ||
  resp.code === 'ETIMEDOUT' ||
  (typeof resp.statusCode === 'number' && resp.statusCode >= 400) ||
  (typeof resp.status === 'number' && resp.status >= 400)
);

if (searchFailed) {
  console.log('[cw-ai] OP search failed — blocking create for manual review');
  return [{
    json: {
      ...g,
      duplicate_found: true,
      op_search_failed: true,
      duplicate_match: { id: 0, subject: 'OpenProject search unavailable — manual review required', score: 1 },
      duplicate_score: 1
    }
  }];
}

if (resp.data && typeof resp.data === 'string') {
  try { resp = JSON.parse(resp.data); } catch (e) { /* keep */ }
} else if (resp.data && typeof resp.data === 'object') {
  resp = resp.data;
}

// Unexpected payload without collection shape — fail safe.
if (!resp || (resp._type && resp._type !== 'WorkPackageCollection' && !resp._embedded)) {
  console.log('[cw-ai] OP search unexpected payload — blocking create');
  return [{
    json: {
      ...g,
      duplicate_found: true,
      op_search_failed: true,
      duplicate_match: { id: 0, subject: 'OpenProject search invalid response — manual review required', score: 1 },
      duplicate_score: 1
    }
  }];
}

const elements = (resp._embedded && resp._embedded.elements) ? resp._embedded.elements : [];
const searchSubject = String(g.op_search_subject || '').toLowerCase();

function wordOverlap(a, b) {
  const wa = new Set(a.split(/\s+/).filter(w => w.length > 2));
  const wb = new Set(b.split(/\s+/).filter(w => w.length > 2));
  if (!wa.size || !wb.size) return 0;
  let inter = 0;
  wa.forEach(w => { if (wb.has(w)) inter++; });
  return inter / Math.max(wa.size, wb.size);
}

let bestMatch = null;
let bestScore = 0;
for (const el of elements) {
  const subj = String(el.subject || '').toLowerCase();
  const score = wordOverlap(searchSubject, subj);
  if (score > bestScore) {
    bestScore = score;
    bestMatch = { id: el.id, subject: el.subject, score };
  }
}

const DUPLICATE_THRESHOLD = 0.5;
const duplicateFound = !!(bestMatch && bestScore >= DUPLICATE_THRESHOLD);
console.log('[cw-ai] duplicate check found=' + duplicateFound + ' score=' + bestScore);

return [{
  json: {
    ...g,
    duplicate_found: duplicateFound,
    op_search_failed: false,
    duplicate_match: bestMatch,
    duplicate_score: bestScore
  }
}];

const g = $input.first().json;
const match = g.duplicate_match || {};
const pubUrl = g.op_public_url || '';
const wpLink = (match.id && match.id !== 0)
  ? ((pubUrl ? pubUrl + '/work_packages/' + match.id : 'WP#' + match.id))
  : '';

let marker;
let noteContent;
if (g.op_search_failed) {
  marker = '<!-- cw-ai-op-search-fail:' + g.message_id + ' -->';
  noteContent = marker + '\n⚠️ **مراجعة يدوية مطلوبة — فشل البحث عن التكرار في OpenProject**\n\n'
    + 'تم إيقاف الإنشاء التلقائي لتجنب إنشاء مهمة مكررة.\n\n'
    + 'التفاصيل: ' + (match.subject || 'OpenProject search failed') + '\n\n'
    + '*يرجى التحقق من OpenProject وتعيين `openproject_wp_id` يدوياً إن لزم.*';
} else {
  marker = '<!-- cw-ai-dup:' + g.message_id + ' -->';
  noteContent = marker + '\n⚠️ **Work Package محتمل مكرر في OpenProject**\n\n'
    + 'لم يتم إنشاء WP جديد. يوجد WP مفتوح مشابه:\n'
    + '- **#' + match.id + '** — ' + (match.subject || '') + '\n'
    + '- تطابق: ' + Math.round((g.duplicate_score || 0) * 100) + '%\n'
    + '- الرابط: ' + wpLink + '\n\n'
    + '*لم يتم تعيين `openproject_wp_id` تلقائياً.*';
}

const pgMarkDoneQuery = 'UPDATE cw_ai_idempotency SET status = \'done\', updated_at = NOW() WHERE chatwoot_message_id = ' + g.message_id + '::BIGINT';

return [{
  json: {
    message_id: g.message_id,
    conversation_id: g.conversation_id,
    account_id: g.account_id,
    note_content: noteContent,
    pg_mark_done_query: pgMarkDoneQuery
  }
}];

const g = $input.first().json;
const aiMeta = g.ai_meta || {};
let subject = String(aiMeta.suggested_wp_subject || aiMeta.project_hint || g.content || 'Chatwoot request').trim();
if ((!subject || subject === '(no text content)' || subject.length < 8) && Array.isArray(g.attachments) && g.attachments.length) {
  const attName = String(g.attachments[0].file_name || g.attachments[0].filename || g.raw_content || g.content || '').trim();
  if (attName) subject = attName;
}
const company = String(g.company || '').trim().toLowerCase();
const companyPrefix = company ? '[' + company.charAt(0).toUpperCase() + company.slice(1) + '] ' : '';
if (companyPrefix && !subject.startsWith('[')) subject = companyPrefix + subject;
if (subject.length > 80) subject = subject.substring(0, 77) + '...';

const priorityMap = {
  low: parseInt(String($env.OPENPROJECT_PRIORITY_LOW_ID || '7'), 10),
  medium: parseInt(String($env.OPENPROJECT_PRIORITY_NORMAL_ID || '8'), 10),
  high: parseInt(String($env.OPENPROJECT_PRIORITY_HIGH_ID || '9'), 10),
  urgent: parseInt(String($env.OPENPROJECT_PRIORITY_HIGH_ID || '9'), 10)
};
const priKey = String(aiMeta.priority || 'medium').toLowerCase();
const priorityId = priorityMap[priKey] || priorityMap.medium;

const fullContent = String(g.raw_content || g.content || '').trim();
const cwBase = String($env.CHATWOOT_URL || '').replace(/\/$/, '');
const convUrl = cwBase ? cwBase + '/app/accounts/' + g.account_id + '/conversations/' + g.conversation_id : '';
const attCtx = g.attachment_context || {};

const descParts = [
  'Created by Chatwoot AI Analysis Pipeline',
  '',
  '## Source',
  '- Chatwoot conversation: ' + (convUrl || g.conversation_id),
  '- Chatwoot message ID: ' + g.message_id,
  '- Customer: ' + (g.sender_name || 'Unknown'),
];
if (g.referenced_op_wp_id) {
  descParts.push('- Related / follow-up to OP#' + g.referenced_op_wp_id);
}
if (g.op_parent_id) {
  descParts.push('- Parent bucket WP: #' + g.op_parent_id);
}
descParts.push(
  '',
  '## Original Message',
  '```',
  fullContent,
  '```',
  '',
  '## AI Analysis (Odoo developer triage)',
  g.analysis_text || ''
);

if (Array.isArray(g.attachments) && g.attachments.length) {
  descParts.push('', '## Attachments (Chatwoot)');
  for (const a of g.attachments) {
    const name = a.file_name || a.filename || ('attachment-' + a.id);
    const url = a.data_url || a.file_url || '';
    descParts.push(url ? '- [' + name + '](' + url + ')' : '- ' + name);
  }
}
if (attCtx.extracted_text) {
  descParts.push('', '## Extracted Attachment Text', '```', String(attCtx.extracted_text), '```');
} else if (attCtx.description) {
  descParts.push('', '## Attachment Description', String(attCtx.description));
}

let description = descParts.join('\n');
if (description.length > 50000) description = description.substring(0, 49997) + '...';

const links = {
  project: { href: '/api/v3/projects/' + g.op_project_id },
  type: { href: '/api/v3/types/' + g.op_type_id },
  priority: { href: '/api/v3/priorities/' + priorityId }
};
if (g.op_parent_id) links.parent = { href: '/api/v3/work_packages/' + g.op_parent_id };
if (g.op_assignee_id) links.assignee = { href: '/api/v3/users/' + g.op_assignee_id };

// Test mode: simulate OP create failure
if ($env.CHATWOOT_AI_TEST_MODE === 'true' && $env.CHATWOOT_AI_TEST_SCENARIO === 'op_create_fail') {
  return [{ json: { ...g, op_create_body: null, wp_subject: subject, force_op_create_fail: true } }];
}

const createBody = {
  subject: subject,
  description: { format: 'markdown', raw: description },
  _links: links
};

return [{ json: { ...g, op_create_body: createBody, wp_subject: subject, op_wp_comment_md: g.op_wp_comment_md || g.analysis_text || '' } }];

const g = $('Build OP Create Payload').first().json;
let resp = $input.first().json;

if (g.force_op_create_fail) {
  return [{ json: { ...g, op_create_success: false, op_create_error: 'simulated_openproject_create_failure' } }];
}

// n8n HTTP node may return body in resp.data as JSON string
if (resp.data && typeof resp.data === 'string') {
  try { resp = JSON.parse(resp.data); } catch (e) { /* keep resp */ }
} else if (resp.data && typeof resp.data === 'object' && resp.data.id) {
  resp = resp.data;
}

if (resp.error || !resp.id) {
  const errMsg = resp.error
    ? (typeof resp.error === 'string' ? resp.error : JSON.stringify(resp.error)).substring(0, 300)
    : 'missing_wp_id_in_response';
  return [{ json: { ...g, op_create_success: false, op_create_error: errMsg } }];
}

const newWpId = parseInt(String(resp.id), 10);
const pubUrl = g.op_public_url || '';
const wpLink = pubUrl ? pubUrl + '/work_packages/' + newWpId : 'WP#' + newWpId;

return [{
  json: {
    ...g,
    op_create_success: true,
    new_wp_id: newWpId,
    wp_link: wpLink,
    pg_mark_done_query: 'UPDATE cw_ai_idempotency SET status = \'done\', updated_at = NOW() WHERE chatwoot_message_id = ' + g.message_id + '::BIGINT'
  }
}];

// HTTP node output replaces context; read from Parse OP Create Response
const g = $('Parse OP Create Response').first().json;
const marker = '<!-- cw-ai-wp-created:' + g.message_id + ' -->';
const stickyNote = g.multi_client_inbox
  ? '- محادثة متعددة العملاء (Dev Needed): **لم** يُثبت `openproject_wp_id` على المحادثة حتى لا تُربط كل الرسائل بنفس التاسك.'
  : '- تم تعيين `openproject_wp_id` على المحادثة.';
const noteContent = marker + '\n✅ **تم إنشاء Work Package في OpenProject**\n\n'
  + '- WP ID: **#' + g.new_wp_id + '**\n'
  + '- العنوان: ' + (g.wp_subject || '') + '\n'
  + '- الرابط: ' + (g.wp_link || '') + '\n'
  + (g.op_parent_id ? '- Parent: **#' + g.op_parent_id + '**\n' : '')
  + (g.referenced_op_wp_id ? '- Related OP: **#' + g.referenced_op_wp_id + '**\n' : '')
  + stickyNote;

return [{
  json: {
    message_id: g.message_id,
    conversation_id: g.conversation_id,
    account_id: g.account_id,
    note_content: noteContent,
    new_wp_id: g.new_wp_id,
    analysis_text: g.analysis_text
  }
}];

const g = $input.first().json;
const errMsg = String(g.op_create_error || 'unknown').substring(0, 300);
const safeErr = errMsg.replace(/'/g, "''");
const marker = '<!-- cw-ai-op-create-fail:' + g.message_id + ' -->';

const noteContent = marker + '\n⚠️ **فشل إنشاء Work Package في OpenProject**\n\n'
  + 'الخطأ: ' + errMsg + '\n\n'
  + '*يرجى إنشاء WP يدوياً وتعيين `openproject_wp_id`.*';

return [{
  json: {
    message_id: g.message_id,
    conversation_id: g.conversation_id,
    account_id: g.account_id,
    note_content: noteContent,
    pg_error_query: "UPDATE cw_ai_idempotency SET status = 'error', updated_at = NOW(), error_message = '" + safeErr.substring(0, 500) + "' WHERE chatwoot_message_id = " + g.message_id + '::BIGINT'
  }
}];
